import { Client } from "pg";
import { q, type Db } from "./db";
import { env } from "./env";
import { log } from "./audit";

export type LiveEvent = { businessId: string; type: "reservation.created" | "reservation.updated" | "conversation.updated"; id: string };

const CHANNEL = "abc_events";

/** Publish inside the caller's transaction: PostgreSQL delivers it only if the transaction commits. */
export async function publish(ev: LiveEvent, db?: Db) {
  await q("SELECT pg_notify($1, $2)", [CHANNEL, JSON.stringify(ev)], db);
}

type Listener = (ev: LiveEvent) => void;
const g = globalThis as unknown as { __abcBus?: { listeners: Set<Listener>; client: Client | null; connecting: boolean } };
const bus = (g.__abcBus ??= { listeners: new Set(), client: null, connecting: false });

async function ensureListening() {
  if (bus.client || bus.connecting) return;
  bus.connecting = true;
  try {
    const client = new Client({ connectionString: env.databaseUrl });
    await client.connect();
    await client.query(`LISTEN ${CHANNEL}`);
    client.on("notification", (n) => {
      if (!n.payload) return;
      try {
        const ev = JSON.parse(n.payload) as LiveEvent;
        for (const l of bus.listeners) l(ev);
      } catch {}
    });
    const drop = () => {
      bus.client = null;
      client.removeAllListeners();
      client.end().catch(() => {});
      if (bus.listeners.size) setTimeout(() => ensureListening(), 2000);
    };
    client.on("error", drop);
    client.on("end", () => { if (bus.client === client) drop(); });
    bus.client = client;
  } catch (e) {
    log("error", "realtime listen failed", { error: (e as Error).message });
    if (bus.listeners.size) setTimeout(() => ensureListening(), 5000);
  } finally {
    bus.connecting = false;
  }
}

/** Subscribe to events for one business. Returns an unsubscribe function. */
export function subscribe(businessId: string, fn: Listener): () => void {
  const wrapped: Listener = (ev) => { if (ev.businessId === businessId) fn(ev); };
  bus.listeners.add(wrapped);
  void ensureListening();
  return () => bus.listeners.delete(wrapped);
}
