import type { Metadata } from "next";
import { notFound } from "next/navigation";
import QRCode from "qrcode";
import { DateTime } from "luxon";
import { TicketActions } from "@/components/TicketActions";
import { StatusBadge } from "@/components/ui";
import { loadContext } from "@/lib/booking/availability";
import { customerCanChange, getReservationByTicketToken } from "@/lib/booking/reservations";
import { env } from "@/lib/env";
import { fmtDateLong, fmtTime, tzLabel } from "@/lib/time";

export const dynamic = "force-dynamic";
// The address of this page is the customer's key to the booking: keep it out of search engines and referrers.
export const metadata: Metadata = { title: "Your reservation", robots: { index: false, follow: false }, referrer: "no-referrer" };

export default async function TicketPage({ params }: { params: Promise<{ token: string }> }) {
  const { token } = await params;
  const r = await getReservationByTicketToken(token);
  if (!r) notFound();
  const ctx = await loadContext(r.business_id);
  const { business: b, policies: p } = ctx;
  const live = ["confirmed", "pending", "checked_in"].includes(r.status);
  // The QR code holds only this page's address: a random ticket id and a signature. No personal data.
  const qr = live ? await QRCode.toString(`${env.appUrl}/t/${token}`, { type: "svg", errorCorrectionLevel: "M", margin: 1, color: { dark: "#0b1f4b", light: "#ffffff" } }) : "";
  const can = customerCanChange(r, p);
  const restaurant = b.type === "restaurant";
  const local = DateTime.fromJSDate(r.starts_at, { zone: b.timezone });
  const headline: Record<string, string> = {
    confirmed: "You're booked", pending: "Awaiting confirmation", checked_in: "Checked in — enjoy", completed: "Thanks for visiting",
    cancelled: "Reservation cancelled", no_show: "Reservation missed",
  };

  return (
    <main className="mx-auto max-w-md px-4 py-6 sm:py-10">
      <article className="ticket" aria-label="Reservation ticket">
        <header className="flex items-center gap-3 px-6 pt-6">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={b.has_logo ? `/api/logo/${b.id}` : "/logo-192.png"} alt="" width={48} height={48} className="size-12 rounded-xl object-contain" />
          <div className="min-w-0 flex-1">
            <p className="truncate font-display text-lg font-bold">{b.name}</p>
            <p className="text-[13px] text-muted">{headline[r.status]}</p>
          </div>
          <StatusBadge status={r.status} />
        </header>

        <div className="px-6 pt-5 pb-6">
          <p className="font-display text-[2.75rem] leading-none font-extrabold tabular" data-testid="ticket-time">{fmtTime(r.starts_at, b.timezone)}</p>
          <p className="mt-1.5 text-lg font-semibold" data-testid="ticket-date">{fmtDateLong(r.starts_at, b.timezone)}</p>
          <p className="text-[13px] text-muted">Local time, {tzLabel(r.starts_at, b.timezone)} ({b.timezone.replace(/_/g, " ")})</p>

          <dl className="mt-5 grid grid-cols-2 gap-x-4 gap-y-3 text-[15px]">
            <div><dt className="text-[13px] text-muted">Name</dt><dd className="font-semibold break-words">{r.customer_name}</dd></div>
            <div><dt className="text-[13px] text-muted">{restaurant ? "Guests" : "People"}</dt><dd className="font-semibold">{r.party_size}</dd></div>
            <div><dt className="text-[13px] text-muted">{restaurant ? "Reservation" : "Service"}</dt><dd className="font-semibold">{r.service_name}</dd></div>
            <div><dt className="text-[13px] text-muted">Until</dt><dd className="font-semibold tabular">{fmtTime(r.ends_at, b.timezone)}</dd></div>
          </dl>
        </div>

        <div className="ticket-perf" />

        <div className="flex flex-col items-center px-6 pt-6 pb-7">
          {live ? (
            <>
              <div className="w-52 rounded-2xl bg-white p-2 ring-1 ring-line" role="img" aria-label="QR code for check-in" dangerouslySetInnerHTML={{ __html: qr }} />
              <p className="mt-3 text-[13px] text-muted">Reference</p>
              <p className="font-display text-2xl font-extrabold tracking-[0.18em] tabular" data-testid="ticket-reference">{r.reference}</p>
              <p className="mt-2 text-center text-[15px] text-ink-soft">
                {r.status === "checked_in" ? "This ticket has been used for check-in." : p.arrival_instructions || "Show this code when you arrive."}
              </p>
            </>
          ) : (
            <div className="w-full rounded-2xl bg-rose-soft px-4 py-5 text-center">
              <p className="font-display text-xl font-bold text-rose">{r.status === "cancelled" ? "This ticket is no longer valid" : r.status === "no_show" ? "This reservation was missed" : "This reservation is complete"}</p>
              <p className="mt-1 text-[15px] text-ink-soft">Reference {r.reference}</p>
            </div>
          )}
        </div>
      </article>

      <TicketActions
        token={token} canChange={can.allowed} whyNot={can.reason} live={live && r.status !== "checked_in"}
        partySize={r.party_size} maxParty={p.max_party_size} date={local.toISODate()!} today={DateTime.now().setZone(b.timezone).toISODate()!}
        maxDate={DateTime.now().setZone(b.timezone).plus({ days: p.max_advance_days }).toISODate()!}
        calendar={{ title: `${r.service_name} at ${b.name}`, start: r.starts_at.toISOString(), end: r.ends_at.toISOString(), location: b.address, reference: r.reference }}
        bookAgainHref={`/b/${b.slug}`}
      />

      <footer className="mt-6 space-y-1 text-center text-[13px] text-muted">
        {(b.address || b.phone) && <p>{[b.address, b.phone].filter(Boolean).join(" — ")}</p>}
        {p.cancellation_policy && <p>{p.cancellation_policy}</p>}
        {p.late_policy && <p>{p.late_policy}</p>}
        <p>A ticket shows that a booking exists. Entry remains subject to the venue's policies.</p>
      </footer>
    </main>
  );
}
